"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import {
  Search,
  ChevronUp,
  ChevronDown,
  Edit,
  Trash2,
  AlertCircle,
  Loader2,
  UserCircle,
  Phone,
  RefreshCw,
  Plus,
} from "lucide-react";
import Layout from "../Layout";

export default function Suppliers() {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState("");
  const [suppliers, setSuppliers] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [sortField, setSortField] = useState("firstName");
  const [sortDirection, setSortDirection] = useState("asc");
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [selectedSupplier, setSelectedSupplier] = useState(null);

  useEffect(() => {
    fetchSuppliers();
  }, []);

  const fetchSuppliers = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    if (!token) {
      setError("Authentification requise. Veuillez vous connecter.");
      setIsLoading(false);
      return;
    }

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/suppliers`, {
        headers: {
          Authorization: `Bearer ${token}`,
          Role: "Superadmin",
        },
      });
      setSuppliers(response.data);
    } catch (err) {
      setError(`Erreur lors de la récupération des fournisseurs : ${err.response?.data?.message || err.message}`);
      console.error("Erreur de récupération des fournisseurs :", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSort = (field) => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const handleCreateSupplier = () => {
    navigate("/CreateSupplier");
  };

  const handleEditSupplier = (id) => {
    navigate(`/EditSupplier/${id}`);
  };

  const handleDeleteSupplier = async (id) => {
    if (window.confirm("Êtes-vous sûr de vouloir supprimer ce fournisseur ?")) {
      try {
        const token = localStorage.getItem("token");
        const role = localStorage.getItem("role");
        await axios.delete(`${process.env.REACT_APP_API_URL}/api/suppliers/${id}`, {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: role,
          },
        });
        setSuppliers(suppliers.filter((s) => s._id !== id));
      } catch (err) {
        setError("Échec de la suppression du fournisseur : " + (err.response?.data?.message || err.message));
      }
    }
  };

  const openDetailsModal = (supplier) => {
    setSelectedSupplier(supplier);
    setIsDetailsModalOpen(true);
  };

  const closeDetailsModal = () => {
    setIsDetailsModalOpen(false);
    setSelectedSupplier(null);
  };

  const filteredAndSortedSuppliers = suppliers
    .filter((supplier) => {
      // Ensure properties exist and provide fallback empty string
      const firstName = (supplier.firstName || "").toLowerCase();
      const lastName = (supplier.lastName || "").toLowerCase();
      const phoneNumber = (supplier.phoneNumber || "").toLowerCase();
      const query = searchQuery.toLowerCase();

      return (
        firstName.includes(query) ||
        lastName.includes(query) ||
        phoneNumber.includes(query)
      );
    })
    .sort((a, b) => {
      const valueA = (a[sortField] || "").toString().toLowerCase();
      const valueB = (b[sortField] || "").toString().toLowerCase();
      return sortDirection === "asc" ? valueA.localeCompare(valueB) : valueB.localeCompare(valueA);
    });

  const getSortIcon = (field) => {
    if (sortField !== field) return null;
    return sortDirection === "asc" ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />;
  };

  return (
    <Layout>
      <div className="max-w-7xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <div>
                <h1 className="text-2xl font-bold tracking-tight">Gestion des Fournisseurs</h1>
                <p className="text-white/80 mt-1">Affichez et gérez les fournisseurs</p>
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={handleCreateSupplier}
                  className="px-4 py-2 bg-white text-[#00717F] rounded-md shadow-sm hover:bg-[#C8A45D/20] flex items-center gap-2 text-sm font-medium transition-colors"
                >
                  <Plus className="h-4 w-4" />
                  Ajouter un fournisseur
                </button>
              </div>
            </div>
          </div>

          <div className="p-6 border-b border-[#C8A45D/30]/50">
            <div className="flex flex-col md:flex-row gap-4">
              <div className="relative flex-1">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Search className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  className="w-full bg-white placeholder:text-gray-400 text-gray-900 text-sm border border-[#C8A45D/30] rounded-md pl-10 pr-3 py-2.5 shadow-sm focus:outline-none focus:ring-2 focus:ring-[#00717F]/50 focus:border-transparent transition-all"
                  placeholder="Rechercher par nom ou téléphone..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={fetchSuppliers}
                  className="px-3 py-2 border border-[#C8A45D/30] rounded-md shadow-sm hover:bg-[#C8A45D/20]/50 flex items-center gap-2 text-sm text-[#00717F] transition-colors"
                >
                  <RefreshCw className="h-4 w-4" />
                  Actualiser
                </button>
              </div>
            </div>
          </div>

          {error && (
            <div className="m-6 p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 rounded-r-md shadow-sm">
              <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              <p className="text-red-700">{error}</p>
            </div>
          )}

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-8 w-8 text-[#00717F] animate-spin" />
                <p className="text-gray-500">Chargement des fournisseurs...</p>
              </div>
            </div>
          ) : filteredAndSortedSuppliers.length === 0 ? (
            <div className="flex flex-col justify-center items-center h-64 text-gray-500">
              <UserCircle className="h-16 w-16 text-gray-300 mb-2" />
              <p className="mb-2">Aucun fournisseur trouvé</p>
            </div>
          ) : (
            <div className="overflow-x-auto p-6">
              <table className="min-w-full divide-y divide-[#C8A45D/30]/50">
                <thead className="bg-[#F5F6FA]">
                  <tr>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("firstName")}
                    >
                      <div className="flex items-center gap-1">Prénom {getSortIcon("firstName")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("lastName")}
                    >
                      <div className="flex items-center gap-1">Nom {getSortIcon("lastName")}</div>
                    </th>
                    <th
                      className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider cursor-pointer hover:bg-[#C8A45D/20]/50 transition-colors"
                      onClick={() => handleSort("phoneNumber")}
                    >
                      <div className="flex items-center gap-1">Téléphone {getSortIcon("phoneNumber")}</div>
                    </th>
                    <th className="py-3.5 px-4 text-left text-xs font-medium text-[#00717F] uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                  {filteredAndSortedSuppliers.map((supplier) => (
                    <tr
                      key={supplier._id}
                      className="hover:bg-[#F5F6FA]/50 transition-colors cursor-pointer border-l-4 border-l-transparent hover:border-l-[#00717F]/70"
                      onClick={() => openDetailsModal(supplier)}
                    >
                      <td className="py-4 px-4">
                        <div className="flex items-center">
                          <div className="h-9 w-9 rounded-full bg-[#00717F]/10 flex items-center justify-center text-[#00717F] mr-3 shadow-sm">
                            <UserCircle className="h-5 w-5" />
                          </div>
                          <div className="text-sm font-medium text-gray-900">{supplier.firstName || "N/A"}</div>
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333">{supplier.lastName || "N/A"}</td>
                      <td className="py-4 px-4 text-sm text-#333333">
                        <div className="flex items-center gap-2">
                          <Phone className="h-4 w-4 text-[#00717F]/60" />
                          {supplier.phoneNumber || "N/A"}
                        </div>
                      </td>
                      <td className="py-4 px-4 text-sm text-#333333" onClick={(e) => e.stopPropagation()}>
                        <div className="flex items-center gap-2 justify-end">
                          <button
                            onClick={() => handleEditSupplier(supplier._id)}
                            className="p-2 text-blue-600 hover:bg-blue-50 rounded-full transition-colors shadow-sm"
                            aria-label="Modifier le fournisseur"
                          >
                            <Edit className="h-5 w-5" />
                          </button>
                          <button
                            onClick={() => handleDeleteSupplier(supplier._id)}
                            className="p-2 text-red-600 hover:bg-red-50 rounded-full transition-colors shadow-sm"
                            aria-label="Supprimer le fournisseur"
                          >
                            <Trash2 className="h-5 w-5" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      {isDetailsModalOpen && selectedSupplier && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-lg shadow-xl max-h-[80vh] overflow-y-auto border border-[#C8A45D/30]">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-[#00717F]">Détails du fournisseur</h2>
              <div className="px-2 py-1 bg-blue-100 text-blue-800 text-xs font-medium rounded-full">Fournisseur</div>
            </div>

            <div className="bg-[#F5F6FA]/50 p-4 rounded-lg mb-4">
              <div className="flex items-center gap-3 mb-3">
                <div className="h-12 w-12 rounded-full bg-[#00717F]/10 flex items-center justify-center text-[#00717F] shadow-sm">
                  <UserCircle className="h-7 w-7" />
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">
                    {(selectedSupplier.firstName || "N/A") + " " + (selectedSupplier.lastName || "N/A")}
                  </h3>
                  <p className="text-sm text-gray-500">Téléphone: {selectedSupplier.phoneNumber || "N/A"}</p>
                </div>
              </div>
            </div>

            <div className="space-y-3 text-gray-700">
              <p>
                <strong className="text-[#00717F]">Prénom:</strong> {selectedSupplier.firstName || "N/A"}
              </p>
              <p>
                <strong className="text-[#00717F]">Nom:</strong> {selectedSupplier.lastName || "N/A"}
              </p>
              <p>
                <strong className="text-[#00717F]">Téléphone:</strong> {selectedSupplier.phoneNumber || "N/A"}
              </p>
              <p>
                <strong className="text-[#00717F]">Rôle:</strong> {selectedSupplier.role || "N/A"}
              </p>
            </div>

            <div className="mt-6 pt-4 border-t border-[#C8A45D/30]/30 flex justify-between items-center">
              <div className="text-xs text-gray-500">
                <p>Créé le : {new Date(selectedSupplier.createdAt).toLocaleString()}</p>
                <p>Mis à jour le : {new Date(selectedSupplier.updatedAt).toLocaleString()}</p>
              </div>
              <button
                onClick={closeDetailsModal}
                className="px-4 py-2 bg-[#00717F] text-white rounded-md hover:bg-[#00717F]/90 transition-colors"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
}
